sys_script_include.script:
var AESCommunicationLifecycle = Class.create();
AESCommunicationLifecycle.prototype = {

    initialize: function() {
        this.TABLE = 'x_733168_aes_communication';

        this.STATE_DRAFT = 'draft';
        this.STATE_SUBMITTED = 'submitted';
        this.STATE_SCHEDULED = 'scheduled';
        this.STATE_PUBLISHED = 'published';
        this.STATE_EXPIRED = 'expired';
        this.STATE_CANCELED = 'canceled';
        this.STATE_RETIRED = 'retired';
    },

    /**
     * Draft -> Submitted
     */
    submit: function(source) {
        var communication = this._resolveCommunication(source);

        if (!communication)
            return this._failure('not_found');

        if (!this._isState(communication, this.STATE_DRAFT))
            return this._failure('invalid_transition');

        return this._changeState(
            communication,
            this.STATE_SUBMITTED
        );
    },

    /**
     * Submitted -> Draft
     */
    returnToDraft: function(source) {
        var communication = this._resolveCommunication(source);

        if (!communication)
            return this._failure('not_found');

        if (!this._isState(communication, this.STATE_SUBMITTED))
            return this._failure('invalid_transition');

        return this._changeState(
            communication,
            this.STATE_DRAFT
        );
    },

    /**
     * Draft / Submitted -> Scheduled
     *
     * publish_date must be in the future.
     */
    schedule: function(source) {
        var communication = this._resolveCommunication(source);

        if (!communication)
            return this._failure('not_found');

        if (
            !this._isState(communication, this.STATE_DRAFT) &&
            !this._isState(communication, this.STATE_SUBMITTED)
        ) {
            return this._failure('invalid_transition');
        }

        if (!this._hasFuturePublishDate(communication))
            return this._failure('invalid_publish_date');

        return this._changeState(
            communication,
            this.STATE_SCHEDULED
        );
    },

    /**
     * Draft / Submitted / Scheduled -> Published
     *
     * actor is optional.
     * Automatic processes can explicitly pass "system".
     */
    publish: function(source, actor) {
        var communication = this._resolveCommunication(source);

        if (!communication)
            return this._failure('not_found');

        if (
            !this._isState(communication, this.STATE_DRAFT) &&
            !this._isState(communication, this.STATE_SUBMITTED) &&
            !this._isState(communication, this.STATE_SCHEDULED)
        ) {
            return this._failure('invalid_transition');
        }

        return this._publish(
            communication,
            actor || gs.getUserName()
        );
    },

    /**
     * Submitted / Scheduled -> Canceled
     */
    cancel: function(source) {
        var communication = this._resolveCommunication(source);

        if (!communication)
            return this._failure('not_found');

        if (
            !this._isState(communication, this.STATE_SUBMITTED) &&
            !this._isState(communication, this.STATE_SCHEDULED)
        ) {
            return this._failure('invalid_transition');
        }

        return this._changeState(
            communication,
            this.STATE_CANCELED
        );
    },

    /**
     * Published -> Expired
     */
    expire: function(source) {
        var communication = this._resolveCommunication(source);

        if (!communication)
            return this._failure('not_found');

        if (!this._isState(communication, this.STATE_PUBLISHED))
            return this._failure('invalid_transition');

        return this._changeState(
            communication,
            this.STATE_EXPIRED
        );
    },

    /**
     * Published -> Retired
     */
    retire: function(source) {
        var communication = this._resolveCommunication(source);

        if (!communication)
            return this._failure('not_found');

        if (!this._isState(communication, this.STATE_PUBLISHED))
            return this._failure('invalid_transition');

        return this._changeState(
            communication,
            this.STATE_RETIRED
        );
    },

    /* =========================================================
     * Private methods
     * ========================================================= */

    /**
     * Accepts either:
     * - a Communication GlideRecord
     * - a Communication sys_id
     */
    _resolveCommunication: function(source) {
        if (gs.nil(source))
            return null;

        // Existing GlideRecord (e.g. current from a UI Action)
        if (
            typeof source == 'object' &&
            typeof source.getTableName == 'function'
        ) {
            if (!source.isValidRecord())
                return null;

            return source;
        }

        // sys_id (e.g. Flow / automation)
        var communication = new GlideRecord(this.TABLE);

        if (!communication.get(source))
            return null;

        return communication;
    },

    _isState: function(communication, state) {
        return communication.getValue('state') == state;
    },

    _hasFuturePublishDate: function(communication) {
        var publishDate = communication.getValue('publish_date');

        if (gs.nil(publishDate))
            return false;

        var publishGdt = new GlideDateTime(publishDate);
        var nowGdt = new GlideDateTime();

        return publishGdt.after(nowGdt);
    },

    _publish: function(communication, actor) {
        communication.setValue(
            'state',
            this.STATE_PUBLISHED
        );

        if (!gs.nil(actor)) {
            communication.setValue(
                'published_by',
                actor
            );
        }

        return this._update(communication);
    },

    _changeState: function(communication, state) {
        communication.setValue('state', state);

        return this._update(communication);
    },

    _update: function(communication) {
        var updatedId = communication.update();

        if (!updatedId)
            return this._failure('update_failed');

        return this._success();
    },

    _success: function() {
        return {
            success: true
        };
    },

    _failure: function(reason) {
        return {
            success: false,
            reason: reason
        };
    },

    type: 'AESCommunicationLifecycle'
};
